import React from 'react';import {createRoot} from 'react-dom/client';
import {CompanionPane} from '../../../src/ui/CompanionPane';import {validateDocument} from '../../../src/core/model';import {applyDocumentPatch,type Patch} from '../../../src/core/patch';import {EXPLANATION_DETAILS_COLUMNS,explanationDetailsRows} from '../../../src/core/explanationDetails';
const initial=validateDocument({schemaVersion:1,id:'qa',title:'Questions',rootViewId:'root',nodes:[{id:'n',label:'Order checks',blockIds:['details']}],edges:[],views:[{id:'root',title:'Root',nodeIds:['n']}],sources:[{id:'source',title:'Supplied evidence',location:'supplied:example',visibility:'private'}],blocks:[{id:'details',title:'Question source',type:'table',columns:EXPLANATION_DETAILS_COLUMNS,rows:explanationDetailsRows({focusQuestion:'Why validate?',sourceCut:'synthetic cut',prerequisites:[],questions:['Who handles failure?']}),sourceIds:['source'],visibility:'private',provenance:'synthetic'}]});
function App(){const [history,setHistory]=React.useState([initial]),[publicMode,setPublic]=React.useState(false),[edit,setEdit]=React.useState(true),[patch,setPatch]=React.useState<Patch|null>(null),[error,setError]=React.useState('');const project=history.at(-1)!;
 const push=(next:typeof initial)=>setHistory(h=>[...h,next]);
 return <><button onClick={()=>setPublic(x=>!x)}>Toggle public</button><button onClick={()=>setEdit(x=>!x)}>Toggle Edit</button><button onClick={()=>setHistory(h=>h.length>1?h.slice(0,-1):h)}>Undo</button><button onClick={()=>push(validateDocument(JSON.parse(JSON.stringify(project))))}>Reload backup</button><button onClick={()=>push({...project,sources:project.sources.map(s=>({...s,title:'Changed evidence'}))})}>Change source without revision</button>
 <CompanionPane project={project} publicMode={publicMode} editMode={edit} anchor={{viewId:'root',nodeId:'n'}} pinned={false} onOpen={()=>{}} onPropose={setPatch}/>
 {patch&&<section aria-label="Patch review"><button onClick={()=>{try{const d=applyDocumentPatch(project,patch).result;push({...d,revision:d.revision+1});setPatch(null);setError('');}catch(e){setError(String(e));}}}>Apply proposed patch</button><p role="alert">{error}</p></section>}</>;
}createRoot(document.getElementById('root')!).render(<App/>);
